import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { booksAPI } from '../utils/api';
import { clearUserSession, getStoredUser } from '../utils/session';

const LandingPage = () => {
  const navigate = useNavigate();
  const [currentUser, setCurrentUser] = useState(null);
  const [stats, setStats] = useState({
    totalBooks: 0,
    totalUsers: 0,
    target: 100000,
    percentageComplete: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setCurrentUser(getStoredUser());
    fetchGlobalStats();

    const interval = setInterval(fetchGlobalStats, 30000);
    return () => clearInterval(interval);
  }, []);

  const fetchGlobalStats = async () => {
    try {
      const response = await booksAPI.getGlobalStats();
      setStats(response.data);
    } catch (error) {
      console.error('Error fetching stats:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleStartJourney = () => {
    navigate(currentUser ? '/dashboard' : '/register');
  };

  const handleLoginOrDashboard = () => {
    navigate(currentUser ? '/dashboard' : '/login');
  };

  const handleLogout = () => {
    clearUserSession();
    setCurrentUser(null);
  };

  const progressWidth = `${Math.min(stats.percentageComplete, 100)}%`;

  return (
    <div className="landing-page">
      <nav className="site-nav">
        <div className="brand-lockup">
          <h1>AKHSS Kharadar</h1>
          <p>100 Years Celebration - Gift of Reading Initiative</p>
        </div>

        <div className="nav-links" aria-label="Primary navigation">
          <a href="#about">About</a>
          <a href="#how-it-works">How It Works</a>
          <a href="#tracker">Tracker</a>

        </div>

        <div className="nav-actions">
          {currentUser ? (
            <>
              <span className="nav-user">Hi, {currentUser.firstName}</span>
              <button className="btn btn-secondary btn-compact" onClick={handleLogout}>
                Logout
              </button>

              <button className="btn btn-compact" onClick={() => navigate('/dashboard')}>
                Dashboard
              </button>
            </>
          ) : (
            <>
              <button className="btn btn-outline btn-compact" onClick={() => navigate('/login')}>
                Login
              </button>
              <button className="btn btn-compact" onClick={() => navigate('/register')}>
                Register
              </button>
            </>
          )}
        </div>
      </nav>

      <main>
        <section className="hero-section" id="about">
          <div className="hero-overlay"></div>
          <div className="hero-content">
            <div className="hero-copy">
              <div className="eyebrow">Celebrating 100 Years of Educational Excellence</div>
              <h2>
                Join Our
                <span> Reading Journey</span>
              </h2>
              <p>
                Help the AKESP community achieve our collective goal of
                <strong> 100,000 books read</strong>. Every completed book becomes
                part of a shared legacy of learning.
              </p>
              <div className="hero-actions">
                <button className="btn btn-light" onClick={handleStartJourney}>
                  {currentUser ? 'Continue Reading' : 'Start Reading'}
                </button>
                <button className="btn btn-glass" onClick={handleLoginOrDashboard}>
                  {currentUser ? 'View Dashboard' : 'Already Registered?'}
                </button>
              </div>
            </div>

            <aside className="hero-tracker" id="tracker">
              <div className="tracker-card">
                <p className="tracker-label">Live Pledge Tracker</p>
                {loading ? (
                  <div className="loading compact-loading">
                    <div className="spinner"></div>
                    <p>Loading statistics...</p>
                  </div>
                ) : (
                  <>
                    <div className="tracker-circle">
                      <strong>{stats.totalBooks.toLocaleString()}</strong>
                      <span>of {stats.target.toLocaleString()} books</span>
                    </div>
                    <div className="tracker-meta">
                      <span>Progress</span>
                      <strong>{stats.percentageComplete}%</strong>
                    </div>
                    <div className="progress-bar slim">
                      <div className="progress-fill" style={{ width: progressWidth }} />
                    </div>
                    <div className="tracker-stats">
                      <div>
                        <strong>{stats.totalUsers || 0}</strong>
                        <span>Readers</span>
                      </div>
                      <div>
                        <strong>{Math.max(stats.target - stats.totalBooks, 0).toLocaleString()}</strong>
                        <span>Books to go</span>
                      </div>
                    </div>
                  </>
                )}
              </div>
            </aside>
          </div>
        </section>

        <section className="content-band" id="how-it-works">
          <div className="section-heading">
            <p className="eyebrow dark">How It Works</p>
            <h2>Simple, trackable, community-wide reading.</h2>
          </div>
          <div className="steps-grid">
            <div className="step-panel">
              <span className="step-number">1</span>
              <h3>Register</h3>
              <p>Create your profile using your B-Form or CNIC number.</p>
            </div>
            <div className="step-panel">
              <span className="step-number">2</span>
              <h3>Read</h3>
              <p>Complete books in any language that supports your growth.</p>
            </div>
            <div className="step-panel">
              <span className="step-number">3</span>
              <h3>Record</h3>
              <p>Add the title, author, and language after each book.</p>
            </div>
            <div className="step-panel">
              <span className="step-number">4</span>
              <h3>Celebrate</h3>
              <p>Watch the live tracker move toward 100,000 books.</p>
            </div>
          </div>
        </section>
      </main>
    </div>
  );
};

export default LandingPage;
